$('export').onclick=()=>{if(!selected||!runs.length)return;const lines=[['クラス',selected.label],['実験条件','各保存記録の実験条件列を参照'],['保存日時','記録ID','班名','保存時の実験条件','実験温度(℃)','時間(s)','入力体積(mL)','濃度(mol/L)','平均減少速度(mol/(L s))','k(s^-1)','初濃度(mol/L)']];for(const r of runs)r.analysis.concentrations.forEach((p,i)=>lines.push([r.created_at,r.id,r.team_label||'',JSON.stringify(r.settings||selected.settings),r.settings?.temp??selected.settings.temp,p.t,r.rows[i].vol,p.c??'',i===0?'':r.analysis.rates[i-1]?.rate??'',r.analysis.k??'',r.analysis.c0??'']));const escape=v=>{let s=String(v);if(/^[=+@\-\t\r\n]/.test(s)&&typeof v==='string')s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const csv='\ufeff'+lines.map(r=>r.map(escape).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='教員用_実験記録.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
