function filteredGroups(){const id=$('class-filter').value;return id?groups.filter(g=>g.class_id===id):groups;}
async function loadClasses(){const result=await LabAPI.rpc('lab_admin_classes',{},true);classes=Array.isArray(result)?result:[];for(const [id,defaultLabel]of[['class-filter','すべてのクラス'],['group-class','講座未所属']]){const select=$(id),value=select.value;select.replaceChildren();const first=document.createElement('option');first.value='';first.textContent=defaultLabel;select.append(first);for(const c of classes){const option=document.createElement('option');option.value=c.id;option.textContent=c.label;select.append(option);}select.value=classes.some(c=>c.id===value)?value:'';}}
function showCode(id,label,code){currentCodeGroup=id;$('code-label').textContent=label;$('group-code').value=code;$('codebox').hidden=false;}
function courseURL(token){const u=new URL('./',location.href);u.hash=new URLSearchParams({class:token}).toString();return u.href;}
function showClassLink(label,token,courseId=activeCourseId){$('class-linkbox').dataset.courseId=courseId;$('class-link-label').textContent=label;$('class-link').value=courseURL(token);$('class-link-anchor').href=$('class-link').value;$('class-link-anchor').textContent=$('class-link').value;$('class-linkbox').hidden=false;}

function teamResults(g){return g.teams?.length?g.teams:g.latest?[g.latest]:[];}
function renderClassSummary(){const box=$('class-summary');box.replaceChildren();const selected=filteredGroups(),count=selected.filter(g=>g.latest).length,p=document.createElement('p');p.className='help';p.textContent=`提出済み ${count} クラス ／ ${selected.length} クラス（班名ごとの最新記録で集約）`;box.append(p);if(!selected.length)return;
const div=document.createElement('div');div.className='scroll';const table=document.createElement('table'),head=document.createElement('tr');['講座','クラス','班名','提出','実験温度(℃)','速度定数 k(s⁻¹)'].forEach(v=>cell(head,v,'th'));table.append(head);const comparison=[];
for(const g of selected){const results=teamResults(g);for(const t of results.length?results:[null]){const row=document.createElement('tr');[g.class_label||'未所属',g.label].forEach(v=>cell(row,v));const teamCell=document.createElement('td');if(t){const link=document.createElement('button');link.type='button';link.className='team-name-button';link.textContent=t.team_label||'旧記録';link.onclick=()=>openTeamResult(g,t.team_label??null);teamCell.append(link);}else teamCell.textContent='—';row.append(teamCell);[t?'提出済み':'未提出',t?.temperature??'—',t?format(t.k):'—'].forEach(v=>cell(row,v));table.append(row);if(t)comparison.push({...g,label:g.label+' / '+(t.team_label||'旧記録'),latest:t});}}
div.append(table);box.append(div);drawClassComparison(box,comparison);}
