$('account-form').onsubmit=async e=>{e.preventDefault();const email=$('new-email').value.trim(),password=$('new-password').value,current=$('current-password').value,button=e.currentTarget.querySelector('button');if(!email&&!password){status('変更するメールアドレスまたはパスワードを入力してください。',true);return;}if(password&&(password.length<8||password!==$('confirm-password').value)){status('新しいパスワードは8文字以上で、確認欄と一致させてください。',true);return;}button.disabled=true;try{await LabAPI.login(LabAPI.currentUser()?.email||$('email').value,current);const changes={};if(email)changes.email=email;if(password)changes.password=password;await LabAPI.updateAccount(changes);$('account-form').reset();status(email?'変更確認メールを送信しました。届いたメールの案内に従って承認してください。':'パスワードを変更しました。');}catch(error){$('current-password').value='';$('new-password').value='';$('confirm-password').value='';status(error.message,true);}finally{button.disabled=false;}};
function drawClassComparison(box,data){
  const valid=data.map(g=>({...g,points:(g.latest?.concentrations||[]).filter(p=>Number.isFinite(p.t)&&Number.isFinite(p.c))})).filter(g=>g.points.length);
  if(!valid.length)return;const colors=['#087e79','#b5672e','#4966aa','#a14b7b','#6b8138','#6e56a0','#267c9a'];
  const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 760 300');svg.setAttribute('role','img');svg.setAttribute('aria-label','各クラスの最新の濃度変化を比較');svg.style.width='100%';
  const all=valid.flatMap(g=>g.points),maxX=Math.max(1,...all.map(p=>p.t))*1.05,minY=Math.min(0,...all.map(p=>p.c)),maxY=Math.max(.001,...all.map(p=>p.c))*1.1,x=v=>70+v/maxX*660,y=v=>250-(v-minY)/(maxY-minY)*220;
  function element(name,attrs,text){const e=document.createElementNS(ns,name);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,String(v));if(text!==undefined)e.textContent=text;svg.append(e);return e;}
  for(let i=0;i<=4;i++){const value=minY+(maxY-minY)*i/4;element('line',{x1:70,x2:730,y1:y(value),y2:y(value),stroke:'#e0e9e2'});element('text',{x:60,y:y(value)+4,'text-anchor':'end','font-size':11,fill:'#678276'},Number(value.toPrecision(3)));element('text',{x:x(maxX*i/4),y:275,'text-anchor':'middle','font-size':11,fill:'#678276'},Math.round(maxX*i/4));}
  element('text',{x:70,y:15,'font-size':11,fill:'#678276'},'濃度（mol/L）');element('text',{x:730,y:295,'text-anchor':'end','font-size':11,fill:'#678276'},'時間（s）');
  const legend=document.createElement('div');legend.className='class-legend';valid.forEach((g,i)=>{const color=colors[i%colors.length],fit=globalThis.LabRegression?.fit(g.points.map(p=>[p.t,p.c]),'concentration');if(fit){const min=Math.min(...g.points.map(p=>p.t)),max=Math.max(...g.points.map(p=>p.t)),curve=Array.from({length:fit.kind==='linear'?2:121},(_,i)=>{const t=min+(max-min)*i/(fit.kind==='linear'?1:120);return[t,fit.predict(t)];}).filter(p=>p.every(Number.isFinite));if(curve.length){const line=element('path',{d:curve.map(([a,b],j)=>(j?'L':'M')+x(a)+','+y(b)).join(' '),fill:'none',stroke:color,'stroke-width':2.5});const title=document.createElementNS(ns,'title');title.textContent=g.label;line.append(title);}}for(const p of g.points)element('circle',{cx:x(p.t),cy:y(p.c),r:3.5,fill:color});const tag=document.createElement('span');tag.style.color=color;tag.textContent='● '+g.label;legend.append(tag);});box.append(svg,legend);
}

function readCourseSettings(){return{temp:25,pressure:+$('pressure').value,volume:+$('volume').value,unit:$('unit').value,input:'total',mode:$('mode').value,c0:$('c0').value,wet:$('wet').checked};}
function fillCourseSettings(course){$('course-name').value=course.label;const cfg=course.settings||groups.find(g=>g.class_id===course.id)?.settings||{pressure:101300,volume:2,unit:'min',mode:'estimate',c0:'',wet:true};for(const id of['pressure','volume','unit','mode','c0'])$(id).value=cfg[id]??'';$('wet').checked=cfg.wet!==false;$('input').value='total';$('mode').onchange();}
function renderCourses(){const box=$('courses');box.replaceChildren();if(!classes.length){const p=document.createElement('p');p.className='help';p.textContent='まだ講座がありません。上のフォームから作成してください。';box.append(p);return;}for(const course of classes){const card=document.createElement('article');card.className='course-card';const title=document.createElement('h3');title.textContent=course.label;const meta=document.createElement('p');meta.className='help';const members=groups.filter(g=>g.class_id===course.id);meta.textContent=`${members.length} クラス · 保存 ${members.reduce((n,g)=>n+Number(g.runs||0),0)} 件`;const button=document.createElement('button');button.className='primary';button.textContent='講座を開く・設定する';button.onclick=()=>openCourse(course.id).catch(e=>status(e.message,true));const rename=document.createElement('button');rename.textContent='講座名を編集';rename.onclick=async()=>{try{await openCourse(course.id);$('course-name').focus();$('course-name').select();}catch(e){status(e.message,true);}};const remove=document.createElement('button');remove.textContent='講座を削除';remove.className='danger';remove.onclick=()=>deleteCourse(course.id,remove);const share=document.createElement('div');share.className='course-share-row';const link=document.createElement('a');link.target='_blank';link.rel='noopener';const copy=document.createElement('button');copy.type='button';copy.textContent='コピー';copy.setAttribute('aria-label',course.label+' の講座リンクをコピー');if(course.link_token){link.href=courseURL(course.link_token);link.textContent=link.href;copy.onclick=()=>copyLectureURL(link.href,copy);}else{link.textContent='リンクを取得するには一覧を更新してください。';copy.disabled=true;}share.append(link,copy);card.append(title,meta,share,button,rename,remove);box.append(card);}}
function syncCourseView(){const course=classes.find(c=>c.id===activeCourseId);$('course-home').hidden=!!course;$('course-detail').hidden=!course;if(course){$('course-title').textContent=course.label;if(course.link_token)showClassLink(course.label,course.link_token,course.id);}}
async function openCourse(id){const course=classes.find(c=>c.id===id);if(!course){closeCourse();return;}if(activeCourseId!==id){closeTeamResult();$('runsbox').hidden=true;$('runs').replaceChildren();selected=null;runs=[];}activeCourseId=id;$('class-filter').value=id;$('group-class').value=id;if($('class-linkbox').dataset.courseId!==id){$('class-linkbox').hidden=true;$('class-link').value='';}await list();fillCourseSettings(classes.find(c=>c.id===id)||course);syncCourseView();}
function closeCourse(){closeTeamResult();activeCourseId='';$('class-filter').value='';$('group-class').value='';$('course-home').hidden=false;$('course-detail').hidden=true;$('runsbox').hidden=true;$('class-linkbox').hidden=true;$('class-link').value='';selected=null;runs=[];}
function renderImportOptions(){const select=$('import-class');select.replaceChildren();const candidates=groups.filter(g=>g.class_id!==activeCourseId);for(const g of candidates){const option=document.createElement('option');option.value=g.id;option.textContent=(g.class_label||'講座未所属')+' / '+g.label;select.append(option);}$('import-container').hidden=!candidates.length||!activeCourseId;}
$('back-courses').onclick=closeCourse;
$('course-settings').onsubmit=async e=>{e.preventDefault();if(!activeCourseId){status('講座を開いてください。',true);return;}const button=e.currentTarget.querySelector('button');button.disabled=true;try{await LabAPI.rpc('lab_admin_course_settings',{p_class_id:activeCourseId,p_settings:readCourseSettings()},true);await list();status('講座の実験条件を保存しました。この講座内の今後の測定に適用されます。保存済みの結果は変わりません。');}catch(error){status(error.message,true);}finally{button.disabled=false;}};
$('import-existing').onsubmit=async e=>{e.preventDefault();if(!activeCourseId||!$('import-class').value)return;if(!confirm('選択したクラスをこの講座に移しますか？保存記録は残り、今後の測定には移動先の講座条件が適用されます。'))return;const button=e.currentTarget.querySelector('button');button.disabled=true;try{await LabAPI.rpc('lab_admin_assign',{p_group_id:$('import-class').value,p_class_id:activeCourseId},true);await list();status('既存のクラスをこの講座に移しました。');}catch(error){status(error.message,true);}finally{button.disabled=false;}};
$('course-name-form').onsubmit=async e=>{e.preventDefault();if(!activeCourseId)return;const name=$('course-name').value.trim();if(!name||Array.from(name).length>100){status('講座名は1～100文字で入力してください。',true);return;}const button=e.currentTarget.querySelector('button');button.disabled=true;try{const c=await LabAPI.rpc('lab_admin_course_rename',{p_class_id:activeCourseId,p_label:name},true);if($('class-linkbox').dataset.courseId===c.id)$('class-link-label').textContent=c.label;await list();status('講座名を変更しました。講座リンクと実験記録はそのまま使用できます。');}catch(error){status(error.message,true);}finally{button.disabled=false;}};
async function deleteCourse(id,button){const c=classes.find(c=>c.id===id);if(!c)return;const members=groups.filter(g=>g.class_id===id),count=members.reduce((n,g)=>n+Number(g.runs||0),0);if(!confirm('「'+c.label+'」を削除しますか？講座・所属クラス '+members.length+' 件・実験記録 '+count+' 件をまとめて完全に削除します。この操作は取り消せません。'))return;if(button)button.disabled=true;try{await LabAPI.rpc('lab_admin_course_delete',{p_class_id:id},true);if(activeCourseId===id)closeCourse();await list();status('講座「'+c.label+'」と、その所属クラス・実験記録を削除しました。');}catch(e){status(e.message,true);}finally{if(button)button.disabled=false;}}
$('delete-course').onclick=()=>deleteCourse(activeCourseId,$('delete-course'));
async function copyLectureURL(value,button){if(!value){status('一覧を更新して講座リンクを取得してください。',true);return;}let copied=false;try{await navigator.clipboard.writeText(value);copied=true;}catch{const area=document.createElement('textarea');area.value=value;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();try{copied=document.execCommand('copy');}catch{}area.remove();}if(copied){status('講座リンクをコピーしました。');if(button){button.textContent='コピーしました';setTimeout(()=>{button.textContent='コピー';},2000);}}else{status('自動コピーが利用できません。表示されたリンクを選択してコピーしてください。',true);}}
function addOrderControls(row,g){const members=filteredGroups(),index=members.findIndex(c=>c.id===g.id),bar=document.createElement('div');bar.className='class-order-controls';const handle=document.createElement('button');handle.type='button';handle.textContent='⠿';handle.className='drag-handle';handle.draggable=true;handle.title='ドラッグして掲載順を変更';handle.setAttribute('aria-label',g.label+' をドラッグして並べ替え');handle.disabled=reorderBusy;handle.ondragstart=e=>{e.dataTransfer.setData('text/plain',g.id);e.dataTransfer.effectAllowed='move';};const position=document.createElement('span');position.textContent='掲載順 '+(index+1);const up=document.createElement('button');up.type='button';up.textContent='上へ';up.disabled=reorderBusy||index===0;up.setAttribute('aria-label',g.label+' を一つ上へ');up.onclick=()=>moveClass(g.id,members[index-1]?.id);const down=document.createElement('button');down.type='button';down.textContent='下へ';down.disabled=reorderBusy||index===members.length-1;down.setAttribute('aria-label',g.label+' を一つ下へ');down.onclick=()=>moveClass(g.id,members[index+1]?.id);row.ondragover=e=>{e.preventDefault();};row.ondrop=e=>{e.preventDefault();return moveClass(e.dataTransfer.getData('text/plain'),g.id);};bar.append(handle,position,up,down);row.append(bar);}
async function moveClass(id,targetId){if(reorderBusy||!activeCourseId||!id||!targetId||id===targetId)return;const ids=filteredGroups().map(g=>g.id),from=ids.indexOf(id),to=ids.indexOf(targetId);if(from<0||to<0)return;ids.splice(to,0,ids.splice(from,1)[0]);reorderBusy=true;document.querySelectorAll('.class-order-controls button').forEach(b=>b.disabled=true);try{await LabAPI.rpc('lab_admin_course_order',{p_class_id:activeCourseId,p_group_ids:ids},true);reorderBusy=false;await list();status('クラスの掲載順を保存しました。生徒のクラス選択画面にも反映されます。');}catch(e){reorderBusy=false;await list().catch(()=>{});status(e.message,true);}finally{reorderBusy=false;}}
function closeTeamResult(){teamRequest++;currentTeamGroup=null;currentTeamRun=null;$('team-detail').hidden=true;$('team-result-content').replaceChildren();$('team-record-info').textContent='';}
async function openTeamResult(g,teamLabel,runId=null){const request=++teamRequest;currentTeamGroup=g.id;currentTeamRun=null;$('team-detail').hidden=false;$('team-title').textContent=g.label+' / '+(teamLabel||'旧記録');$('team-record-info').textContent='保存データを読み込んでいます…';$('team-result-content').replaceChildren();try{const record=await LabAPI.rpc('lab_admin_team_result',{p_group_id:g.id,p_team_label:teamLabel,p_run_id:runId},true);if(request!==teamRequest)return;currentTeamRun=record.id;$('team-record-info').textContent=(runId?'指定した保存データ':'この班の最新の保存データ')+' ／ '+new Date(record.created_at).toLocaleString('ja-JP');LabTeamResults.render($('team-result-content'),record);$('team-detail').scrollIntoView?.({behavior:'smooth',block:'start'});status('班の入力結果と3種類の回帰グラフを表示しました。');}catch(e){if(request!==teamRequest)return;$('team-record-info').textContent=e.message;status(e.message,true);}}
$('close-team-detail').onclick=closeTeamResult;
